/**
 * The localized copy of the bundled foundation foods.
 *
 * English is the text of the two seed files; every other language has a
 * `data/foundationFoods<Xx><Xx>.json` generated by `scripts/generate-foundation-food-locales.js`,
 * joined to its seed row by `external_id`.
 *
 * Like a catalogue exercise, a seeded food is written once, in the language of that first boot, and
 * never re-localized. Anything that needs the English text (the AI food list, the name match of a
 * meal estimate) or has to find a food typed in another language (search) asks this module instead
 * of trusting the stored words.
 */

import commonFoundationFoods from '@/data/common_foundation_foods.json';
import usdaFoundationFoods from '@/data/usda_foundation_foods.json';
import i18n, { EN_US, FOUNDATION_FOOD_COPIES_BY_LOCALE } from '@/lang/lang';
import { type BundledText, type StoredBundledText, swapBundledText } from '@/utils/bundledText';

export interface FoundationFoodCopy {
  externalId: string;
  name: string;
  description: string;
}

/** What this module reads off a stored food (a `Food` model satisfies it). */
export type StoredFoodText = StoredBundledText & { externalId?: string; source?: string };

type CopyLocale = keyof typeof FOUNDATION_FOOD_COPIES_BY_LOCALE;

const COMBINING_MARKS = /[̀-ͯ]/g;

let englishCopies: Map<string, FoundationFoodCopy> | undefined;
const localizedCopies = new Map<string, Map<string, FoundationFoodCopy>>();

/** The first row wins for a repeated `external_id`, as in the seeder. */
function english(): Map<string, FoundationFoodCopy> {
  if (!englishCopies) {
    englishCopies = new Map();
    for (const row of [...usdaFoundationFoods, ...commonFoundationFoods]) {
      if (!englishCopies.has(row.external_id)) {
        englishCopies.set(row.external_id, {
          externalId: row.external_id,
          name: row.name,
          description: row.description,
        });
      }
    }
  }

  return englishCopies;
}

/** `undefined` for English and for a language with no copy file. */
function localized(locale: string | undefined): Map<string, FoundationFoodCopy> | undefined {
  if (!locale || !(locale in FOUNDATION_FOOD_COPIES_BY_LOCALE)) {
    return undefined;
  }

  let copies = localizedCopies.get(locale);
  if (!copies) {
    copies = new Map(
      FOUNDATION_FOOD_COPIES_BY_LOCALE[locale as CopyLocale].map((copy) => [copy.externalId, copy])
    );
    localizedCopies.set(locale, copies);
  }

  return copies;
}

function currentLocale(): string | undefined {
  return i18n.resolvedLanguage ?? i18n.language;
}

/** A seed row with its name and description in `locale`; unchanged when there is no copy for it. */
export function localizeFoundationFood<
  T extends { externalId: string; name: string; description: string },
>(food: T, locale: string | undefined = currentLocale()): T {
  const copy = localized(locale)?.get(food.externalId);

  return copy ? { ...food, name: copy.name, description: copy.description } : food;
}

/**
 * A stored food's name and description in `locale` (English when there is no copy for it). Only a
 * foundation food's own bundled words are swapped: see `swapBundledText`.
 */
export function getFoundationFoodText(
  food: StoredFoodText,
  locale: string | undefined
): BundledText {
  const original =
    food.source === 'foundation' && food.externalId ? english().get(food.externalId) : undefined;
  if (!original) {
    return { name: food.name, description: food.description };
  }

  const copies = Object.keys(FOUNDATION_FOOD_COPIES_BY_LOCALE).map((language) =>
    localized(language)?.get(original.externalId)
  );

  return swapBundledText(food, localized(locale)?.get(original.externalId) ?? original, [
    original,
    ...copies,
  ]);
}

export function getEnglishFoundationFoodText(food: StoredFoodText): BundledText {
  return getFoundationFoodText(food, EN_US);
}

/** Lowercase without diacritics. SQLite's `LIKE` only ignores case for ASCII. */
function fold(text: string): string {
  return text.toLowerCase().normalize('NFD').replace(COMBINING_MARKS, '');
}

/**
 * The foundation foods whose English or `locale` copy contains `term`, whatever language the
 * database row was written in.
 */
export function findFoundationFoodExternalIds(
  term: string,
  {
    includeDescription = false,
    locale = currentLocale(),
  }: { includeDescription?: boolean; locale?: string } = {}
): string[] {
  const needle = fold(term).trim();
  if (!needle) {
    return [];
  }

  const matches = (copy: FoundationFoodCopy) =>
    fold(copy.name).includes(needle) ||
    (includeDescription && fold(copy.description).includes(needle));
  const ids = new Set<string>();
  for (const copies of [english(), localized(locale)]) {
    for (const copy of copies?.values() ?? []) {
      if (matches(copy)) {
        ids.add(copy.externalId);
      }
    }
  }

  return [...ids];
}
